<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$events=$pdo->query("SELECT DISTINCT e.id,e.name,e.event_date FROM bdc_test_events e JOIN bdc_test_scoring_rounds r ON r.event_id=e.id AND r.status<>'archived' ORDER BY e.event_date DESC,e.name")->fetchAll();$rounds=$pdo->query("SELECT id,event_id,division,round_type,status FROM bdc_test_scoring_rounds WHERE status<>'archived' ORDER BY event_id,division,FIELD(round_type,'heats','semifinal','final'),id")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test Live Screen Projector</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.workspace{border-radius:16px}.option{border:1px solid #dee2e6;border-radius:12px;padding:18px;background:#fff}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../scoring-tests/select-mode.php">Scoring Tests</a><a class="btn btn-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4"><div class="alert alert-warning fw-bold">TEST MODE · Projection data comes only from Scoring Tests.</div><h1 class="h2">Test Live Screen Projector</h1><p class="text-muted mb-4">Select Event → Category → Round. Applicable Test projection options appear below.</p><div class="card workspace shadow-sm mb-4"><div class="card-body"><div class="row g-3"><div class="col-md-5"><label class="form-label fw-bold">Event</label><select id="event" class="form-select"><option value="">Select event...</option><?php foreach($events as $e):?><option value="<?=(int)$e['id']?>"><?=e($e['name'])?><?=!empty($e['event_date'])?' · '.e($e['event_date']):''?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label fw-bold">Category / Division</label><select id="division" class="form-select" disabled><option>Select category...</option></select></div><div class="col-md-3"><label class="form-label fw-bold">Round</label><select id="round" class="form-select" disabled><option>Select round...</option></select></div></div></div></div><div id="selected" class="d-none"><div class="d-flex justify-content-between align-items-center mb-3"><h2 id="selectedTitle" class="h4 mb-0"></h2><a id="control" class="btn btn-warning">Screen & Layout Settings</a></div><div id="options" class="row g-3"></div></div></main><script>const rounds=<?=json_encode($rounds,JSON_UNESCAPED_SLASHES)?>,event=document.querySelector('#event'),division=document.querySelector('#division'),round=document.querySelector('#round'),label=s=>String(s).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());event.onchange=()=>{const id=Number(event.value),v=[...new Set(rounds.filter(r=>Number(r.event_id)===id).map(r=>r.division))];division.innerHTML='<option value="">Select category...</option>'+v.map(x=>`<option value="${x}">${label(x)}</option>`).join('');division.disabled=!id;round.disabled=true;document.querySelector('#selected').classList.add('d-none')};division.onchange=()=>{const v=rounds.filter(r=>Number(r.event_id)===Number(event.value)&&r.division===division.value);round.innerHTML='<option value="">Select round...</option>'+v.map(x=>`<option value="${x.id}">${label(x.round_type)}</option>`).join('');round.disabled=!division.value;document.querySelector('#selected').classList.add('d-none')};round.onchange=()=>{const r=rounds.find(x=>Number(x.id)===Number(round.value));if(!r)return;document.querySelector('#selectedTitle').textContent=event.options[event.selectedIndex].text.split(' · ')[0]+' · '+label(r.division)+' · '+label(r.round_type);document.querySelector('#control').href='test-control.php?round_id='+r.id;const t=r.round_type==='heats'?[['judges','Judges'],['competitors','Competitors'],['scoring','Scoring Status'],['callbacks','Callback Reveal']]:r.round_type==='semifinal'?[['judges','Judges'],['competitors','Competitors'],['scoring','Scoring Status'],['finalists','Finalists Reveal']]:[['judges','Judges'],['competitors','Finalists / Couples'],['scoring','Scoring Status'],['results','Final Ranking'],['winners','Winner Reveal']];document.querySelector('#options').innerHTML=t.map(x=>`<div class="col-md-6"><div class="option"><h3 class="h5">${x[1]}</h3><a class="btn btn-outline-danger" target="_blank" href="test-projection.php?round_id=${r.id}&type=${x[0]}">Open Test Projection</a></div></div>`).join('');document.querySelector('#selected').classList.remove('d-none')};</script></body></html>